using System;using System.IO;using System.Linq;using System.Collections.Generic;using System.Drawing;using System.Threading;using Prometheus;
class Tests023 {
 static List<string> checks=new List<string>();static void Check(bool value,string name){if(!value)throw new Exception("FAIL "+name);checks.Add(name);Console.WriteLine("PASS "+name);}
 static byte[] Raw(string args){using(var process=Tools.Start(Tools.FFmpeg,args)){string errors="";process.ErrorDataReceived+=(s,e)=>{if(e.Data!=null)errors+=e.Data;};process.BeginErrorReadLine();using(var memory=new MemoryStream()){process.StandardOutput.BaseStream.CopyTo(memory);process.WaitForExit();if(process.ExitCode!=0)throw new Exception(errors);return memory.ToArray();}}}
 static void Solid(byte[] bytes,int width,int height,int count,string label){int size=width*height*4;Check(bytes.Length==size*count,label+" frame count");for(int i=0;i<count;i++){int pixel=i*size+(height/2*width+width/2)*4;if(bytes[pixel+2]<170||bytes[pixel+1]>70||bytes[pixel]>70)throw new Exception("Black/wrong frame "+i+" "+label);}Check(true,label+" no black frames across cuts");}
 static void Main(string[] args){string root=Path.GetFullPath(args[0]);Tools.Root=Path.GetFullPath(args[1]);var token=CancellationToken.None;string image=Path.Combine(root,"solid023.png");using(var bitmap=new Bitmap(64,36)){using(var graphics=Graphics.FromImage(bitmap))graphics.Clear(Color.FromArgb(220,20,20));bitmap.Save(image,System.Drawing.Imaging.ImageFormat.Png);}var asset=Media.Inspect(image,token);var editor=new Editor();editor.Commit(p=>{p.assets.Add(asset);Media.Insert(p,asset.id,p.Active.tracks.First(t=>t.kind=="video").id,0);p.Active.clips[0].duration=new Rational(1,1);});var original=Store.Copy(editor.Project);foreach(int frame in new[]{2,7,17,31,49})editor.CutSelection(new List<string>(),frame/60.0);Check(editor.Project.Active.clips.Count==6&&Math.Abs(editor.Project.Active.clips.Sum(c=>c.duration.Seconds)-1)<0.000001,"image splits preserve total duration");
  if(args.Length>2&&args[2]=="baseline"){Solid(Raw(Rendering.Build(editor.Project,true,false,64,36,60,"raw",0)),64,36,60,"baseline image split");return;}
  Solid(Raw(Rendering.Build(editor.Project,true,false,64,36,60,"raw",0)),64,36,60,"60 fps image split");Solid(Raw(Rendering.Build(editor.Project,true,false,64,36,15,"raw",0)),64,36,15,"15 fps preview image split");foreach(int frame in new[]{2,7,17,31,49})using(var bitmap=Rendering.Frame(editor.Project,frame/60.0,token)){Check(bitmap.GetPixel(320,180).R>170,"paused preview exact image cut frame "+frame);}
  string export=Path.Combine(root,"image-cuts023.mp4");Rendering.Export(editor.Project,export,token);Solid(Raw("-v error -i "+Tools.Q(export)+" -vf scale=64:36 -pix_fmt bgra -f rawvideo pipe:1"),64,36,60,"exported image split");
  var av=new Editor();var media=Media.Inspect(Path.Combine(root,"source.mp4"),token);av.Commit(p=>{p.assets.Add(media);Media.Insert(p,media.id,p.Active.tracks.First(t=>t.kind=="video").id,0);});string id=av.Project.Active.clips.First(c=>av.Project.Active.tracks.Find(t=>t.id==c.track_id).kind=="video").id;double full=av.Project.Active.clips.Find(c=>c.id==id).duration.Seconds;av.Trim(id,false,999);Check(av.Project.Active.clips.Find(c=>c.id==id).duration.Seconds==full,"extension at full source stops without error");av.Trim(id,true,-999);Check(av.Project.Active.clips.Find(c=>c.id==id).source_in.Seconds==0,"left trim stops at source beginning");av.Trim(id,false,full/2);av.Trim(id,false,999);Check(Math.Abs(av.Project.Active.clips.Find(c=>c.id==id).duration.Seconds-full)<0.000001,"linked extension restores only available source range");av.Trim(id,false,-999);Check(av.Project.Active.clips.All(c=>c.duration.Seconds>=1.0/60-0.000001),"trim retains minimum linked frame");
  av.Reset(Store.Copy(original));id=av.Project.Active.clips[0].id;av.Trim(id,false,8);Check(av.Project.Active.clips[0].duration.Seconds==8,"still image extends beyond initial duration");long revision=av.Project.revision;Check(!av.CutSelection(new List<string>(),0)&&av.Project.revision==revision,"cut on boundary is no-op without extra fragment");av.CutSelection(new List<string>{id},2);var selected=av.Project.Active.clips.First(c=>c.id!=id);av.MoveSelection(av.Project.Active.clips.Select(c=>c.id).ToList(),id,1,null);Check(av.Project.Active.clips.Find(c=>c.id==id).timeline_start.Seconds==1&&av.Project.Active.clips.Find(c=>c.id==selected.id).timeline_start.Seconds==3,"multi move preserves distances");av.Undo();Check(av.Project.Active.clips.Find(c=>c.id==id).timeline_start.Seconds==0,"multi move undoes atomically");av.Commit(p=>p.Active.tracks[0].locked=true);string before=Store.Encode(av.Project);try{av.MoveSelection(new List<string>{id,selected.id},id,1,null);throw new Exception("locked move accepted");}catch{Check(Store.Encode(av.Project)==before,"locked multi move leaves whole group unchanged");}Check(!av.CutSelection(new List<string>(),1),"cut all skips locked tracks");
  var both=new Editor();both.Commit(p=>{p.assets.Add(media);Media.Insert(p,media.id,p.Active.tracks.First(t=>t.kind=="video").id,0);});var video=both.Project.Active.clips.First(c=>both.Project.Active.tracks.Find(t=>t.id==c.track_id).kind=="video");both.CutSelection(new List<string>{video.id},0.5);Check(both.Project.Active.clips.Count==3&&both.Project.Active.clips.Count(c=>both.Project.Active.tracks.Find(t=>t.id==c.track_id).kind=="audio")==1,"selected cut affects only selected clip despite link");both.Undo();both.CutSelection(new List<string>(),0.5);Check(both.Project.Active.clips.Count==4&&both.Project.Active.link_groups.Count==2,"unselected cut splits all clips and preserves paired links");
  File.WriteAllText(Path.Combine(root,"checks-edit023.json"),Store.Json().Serialize(new{status="PASS",checks=checks}));
 }
}
